    template: 'v3',
    discover: [
      B.text('039_d_situation', 'Internet ei tööta', 'Jaani kodus ei tööta internet juba kaks päeva. Ta helistab interneti klienditeenindusse. Kõigepealt räägib automaat, siis vastab teenindaja.'),
      B.listening('039_d_listen', 'Kuula kõnet.', 'Õpetaja loeb kõne kaks korda. Kirjuta lünka 1–2 sõna.', [
        'Automaat: Tere! Teie kõne on meile oluline. Palun oodake.', 'Teenindaja: Tere! Siin Anneli. Mis küsimuses te helistate?', 'Jaan: Tere! Minu kodus ei tööta internet.',
        'Anneli: Mis on teie nimi ja aadress?', 'Jaan: Jaan Kask, Pärna tänav 8, Tallinn.', 'Anneli: Vabandust, ma ei kuulnud. Palun korrake tänavat.', 'Jaan: Pärna. P, Ä, R, N, A.',
        'Anneli: Aitäh. Ma ühendan teid tehnikuga.', 'Anneli: Tehnik helistab teile tagasi täna kell kolm.',
      ], ['Teenindaja nimi on [Anneli].', 'Jaani kodus ei tööta [internet].', 'Jaan elab [Pärna] tänaval.', 'Anneli palub Jaanil tänavat [korrata].', 'Anneli ühendab Jaani [tehnikuga].', 'Tehnik helistab tagasi kell [kolm|3|15].', 'Jaan elab [Tallinnas].', 'Jaan ütleb tänava nime [tähthaaval].']),
      B.reading('039_d_read', 'Loe klienditeeninduse infot.', 'Loe teksti ja vasta küsimustele.', 'Kuidas meile helistada?',
        'Meie klienditeenindus on avatud iga päev kell 8–20. Helistage numbril 1717. Kõigepealt kuulete automaati. Valige number. Interneti küsimused: vajutage 1. Arve küsimused: vajutage 2. Uus leping: vajutage 3. Siis palun oodake. Tavaliselt vastab teenindaja viie minuti jooksul. Kui ootamine on liiga pikk, võite jätta sõnumi. Siis helistame teile tagasi samal päeval. Enne kõnet otsige üles lepingu number. Teenindaja küsib ka teie nime ja aadressi. Me räägime eesti, vene ja inglise keeles. Kui teenindaja ei saa probleemi lahendada, ühendab ta teid tehnikuga. Lihtsaid küsimusi saate lahendada ka meie kodulehel.',
        [['Millal on klienditeenindus avatud?', 'iga päev kell 8–20|kell 8–20'], ['Mis numbrit vajutad arve küsimusega?', '2|kaks'], ['Millal vastab tavaliselt teenindaja?', 'viie minuti jooksul'], ['Mida teha, kui ootamine on pikk?', 'jätta sõnum|jäta sõnum'], ['Mida peab enne kõnet üles otsima?', 'lepingu numbri|lepingu number'], ['Kellega ühendab teenindaja, kui ta ei saa aidata?', 'tehnikuga'], ['Mis numbril tuleb helistada?', '1717'], ['Mis keeltes teenindajad räägivad?', 'eesti, vene ja inglise keeles|eesti, vene ja inglise']]),
      B.notice('039_d_notice', 'Märka: telefonis', ['Teenindaja: **Mis küsimuses** te helistate?', 'Teenindaja: **Palun oodake.** · **Ma ühendan** teid…', 'Klient: **Ma helistan**, sest internet ei tööta.', 'Kui ei kuule: **Palun korrake!** · **Palun öelge tähthaaval.**', 'Lõpus: **Kas ma saan veel aidata?** · **Aitäh, head päeva!**']),
      B.dialogue('039_d_dialog', 'Kõne panka.', 'Täida dialoog sobivate sõnadega.', 'Teenindaja', 'Olga', [
        ['A', 'Tere! Pank, Raul kuuleb. Mis [küsimuses] te helistate?'], ['B', 'Tere! Ma ei saa oma [kaarti] kasutada.'], ['A', 'Palun [oodake], ma vaatan.'],
        ['B', 'Vabandust, ma ei [kuule] teid hästi.'], ['A', 'Palun öelge oma nimi [tähthaaval].'], ['B', 'O, L, G, A. Olga Ivanova.'], ['A', 'Aitäh. Ma [ühendan] teid kaardiosakonnaga.'], ['B', 'Aitäh! Ma [ootan].']]),
      B.errorfix('039_d_fix', 'Paranda viga.', 'Kirjuta lause õigesti.', [['Palun ootage.', 'Palun oodake.'], ['Ma ei kuulen teid.', 'Ma ei kuule teid.'], ['Mis küsimus te helistate?', 'Mis küsimuses te helistate?'], ['Ma ühendan teie tehnikuga.', 'Ma ühendan teid tehnikuga.'], ['Palun korda, härra.', 'Palun korrake.'], ['Me helistame teid tagasi.', 'Me helistame teile tagasi.'], ['Ma ühendan teie arstiga.', 'Ma ühendan teid arstiga.'], ['Palun ütle nimi tähthaaval, proua.', 'Palun öelge nimi tähthaaval.']]),
      B.translation('039_d_tr', 'Tõlgi eesti keelde.', 'Kirjuta lause eesti keeles.', ['Подождите, пожалуйста.', 'Я вас не слышу.', 'Повторите, пожалуйста.', 'Я звоню, потому что не работает интернет.', 'Соединяю вас с врачом.', 'Я звоню по поводу посылки.', 'Подождите минутку.', 'Скажите фамилию по буквам.']),
      B.speaking('039_d_say', 'Helista klienditeenindusse.', 'Paariline on teenindaja. Ütle, mis küsimuses sa helistad.', ['Tervita ja ütle oma nimi.', 'Ütle, mis ei tööta.', 'Ütle nimi tähthaaval.', 'Küsi, mis on järgmine samm.', 'Täna ja jäta hüvasti.'], [60, 120], ['Ma helistan, sest…', 'Palun korrake!', 'Millal te helistate tagasi?']),
      B.writing('039_d_write', 'Märkmed kõnest.', 'Kirjuta Jaani kõnest 6–8 lauset: kuhu ta helistas, miks ja mis edasi saab.', [6, 8], ['helistas', 'sest', 'tehnik', 'tagasi'], 2),
    ],
