    discover: [
      B.text('040_d_situation', 'Kordame', 'Enne kontrolli kordame mooduli tähtsamat: aja broneerimine ja muutmine, modaalverbid, vormid ja juhised, telefon ja klienditeenindus.'),
      B.notice('040_d_notice', 'Mooduli kokkuvõte', ['Aeg: **Soovin aega… Kas … sobib? Kas on võimalik varem / hiljem?**', 'Modaalverbid: **pean minema** · **saan / võin minna** · **ei tohi minna**', 'Juhis: **täitke, kirjutage, valige, märkige, ärge unustage**', 'Telefon: **Mis küsimuses? Palun oodake. Ma ühendan. Palun korrake.**', 'Päev: **esmaspäeval, reedel, järgmisel nädalal**']),
      B.reading('040_d_read', 'Loe: Markuse päev.', 'Loe teksti ja vasta küsimustele.', 'Asjaajamise päev',
        'Markusel on vaba päev, aga tal on palju asju ajada. Hommikul helistab ta hambaarstile. Ta soovib aega järgmiseks nädalaks. Esmaspäev on kinni, aga teisipäeval kell neli on vaba. See sobib. Siis läheb Markus linnavalitsusse. Ta peab registreerima uue elukoha. Ta peab võtma järjekorranumbri ja ootama. Ametnik annab talle vormi. Markus täidab vormi trükitähtedega. Ta unustab allkirja, aga ametnik märkab seda. Ametnik ütleb, et vastus tuleb e-postiga kümne päeva jooksul. Pärastlõunal helistab Markus internetifirmasse. Teenindaja küsib tema nime ja aadressi. Markus ütleb tänava nime tähthaaval. Siis ühendab teenindaja ta tehnikuga. Tehnik saab tulla alles reedel. Õhtul on Markus väsinud, aga rahul.',
        [['Millal on Markuse aeg hambaarstil?', 'teisipäeval kell neli|teisipäeval kell 16'], ['Mida Markus linnavalitsuses teeb?', 'registreerib elukoha|registreerib uue elukoha'], ['Kuidas Markus vormi täidab?', 'trükitähtedega'], ['Mida Markus unustab?', 'allkirja|allkiri'], ['Millal tehnik tuleb?', 'reedel']]),
      B.truefalse('040_d_tf', 'Õige või vale?', 'Loe Markuse teksti uuesti.', [['Markus töötab sel päeval.', false], ['Esmaspäeval ei ole hambaarstil vaba aega.', true], ['Linnavalitsuses ei pea ootama.', false], ['Ametnik märkab, et allkiri puudub.', true], ['Tehnik tuleb samal päeval.', false]]),
      B.manymatch('040_d_match', 'Mida öelda?', 'Ühenda olukord ja lause.', ['Sa tahad aega arstile.', 'Pakutud aeg on liiga vara.', 'Sa ei kuulnud numbrit.', 'Sa tahad teada, kas tohib istuda.', 'Teenindaja küsib, miks sa helistad.'], ['Soovin aega arstile.', 'Kas on võimalik hiljem tulla?', 'Palun korrake numbrit.', 'Kas ma võin siin istuda?', 'Ma helistan arve pärast.'], 'full', 'g_use'),
      B.wordforms('040_d_forms', 'Õige vorm.', 'Kirjuta sõna õiges vormis.', [['ootama', 'pean …', 'ootama'], ['ootama', 'saan …', 'oodata'], ['täitma', 'teie käsk', 'täitke'], ['kirjutama', 'teie käsk', 'kirjutage'], ['reede', 'millal?', 'reedel'], ['tohtima', 'ma (eitus)', 'ei tohi']]),
      B.gaps('040_d_gaps', 'Kordame vorme.', 'Kirjuta sulgudes olev sõna õiges vormis.', ['Ma [pean] homme tööl olema. (pidama)', 'Kas ma võin siin [istuda]? (istuma)', 'Saalis ei tohi [süüa]. (sööma)', 'Palun [täitke] vorm. (täitma, teie)', 'Kas teile sobib [neljapäeval]? (neljapäev)', 'Palun [oodake]! (ootama, teie)']),
      B.transformation('040_d_trans', 'Ütle teisiti.', 'Kirjuta lause antud algusega.', [['Suitsetamine on keelatud.', 'Siin ei tohi …', 'Siin ei tohi suitsetada.'], ['Ma tahan aega hambaarstile.', 'Soovin …', 'Soovin aega hambaarstile.'], ['Täida vorm!', 'Palun …', 'Palun täitke vorm!'], ['Mul on võimalik reedel tulla.', 'Ma saan …', 'Ma saan reedel tulla.|Ma saan tulla reedel.'], ['Korda!', 'Palun …', 'Palun korrake!']]),
      B.errorfix('040_d_fix', 'Paranda viga.', 'Kirjuta lause õigesti.', [['Ma pean minna.', 'Ma pean minema.'], ['Kas teil on reede vaba aega?', 'Kas teil on reedel vaba aega?'], ['Täitage vorm.', 'Täitke vorm.'], ['Siin ei tohi suitsetama.', 'Siin ei tohi suitsetada.'], ['Mis küsimus te helistate?', 'Mis küsimuses te helistate?']]),
      B.crossword('040_d_cross', 'Mooduli sõnad.', 'Kirjuta sõna vihje järgi.', [['Nimi, mille kirjutad dokumendi lõppu', 'allkiri'], ['Kui aeg ei ole vaba, on see …', 'kinni'], ['Paber, millega midagi palud', 'taotlus'], ['Inimesed ootavad seal üksteise järel', 'järjekord'], ['Telefonis: palun …, ma vaatan kalendrit', 'oodake'], ['Raamatus või telefonis päevad ja ajad', 'kalender']]),
      B.translation('040_d_tr', 'Tõlgi eesti keelde.', 'Kirjuta lause eesti keeles.', ['Я хочу записаться к врачу.', 'Можно прийти раньше?', 'Здесь нельзя есть.', 'Заполните бланк печатными буквами.', 'Подождите, пожалуйста, я вас соединяю.']),
      B.dictation('040_d_dict', 'Etteütlus.', 'Kuula ja kirjuta laused.', ['Soovin aega hambaarstile.', 'Te peate ootama.', 'Siin ei tohi suitsetada.', 'Palun täitke vorm.', 'Ma ühendan teid tehnikuga.'], 5),
      B.wordorder('040_d_order', 'Pane lause kokku.', 'Kirjuta sõnad õiges järjekorras.', ['Markus helistab hommikul hambaarstile.', 'Ta peab võtma järjekorranumbri.', 'Ametnik annab talle vormi.', 'Tehnik saab tulla alles reedel.', 'Õhtul on Markus väsinud.']),
      B.speaking('040_d_say', 'Proovieksam: teenindus.', 'Vasta paarilise küsimustele täislausega.', ['Kuhu sa viimati aega broneerisid?', 'Mida sa pead tööl või koolis tegema?', 'Mida ei tohi sinu töökohas teha?', 'Kuhu sa viimati helistasid ja miks?'], [45, 90]),
      B.writing('040_d_write', 'Kordame kirjutamist.', 'Kirjuta 5–7 lauset oma asjaajamise päevast.', [5, 7], ['pean', 'helistasin', 'aeg', 'vorm'], 2),
    ],
